alter table public.mission_rescue_cases add column if not exists offered_agency_id uuid references public.agencies(id), add column if not exists offered_at timestamptz;
create or replace function public.offer_mission_rescue_to_backup(p_job_id uuid,p_agency_id uuid) returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ declare v_case public.mission_rescue_cases; begin if public.current_role()<>'platform_admin' then raise exception 'PLATFORM_ADMIN_REQUIRED'; end if; select * into v_case from public.mission_rescue_cases where job_id=p_job_id and status='open' limit 1; if v_case.id is null then raise exception 'RESCUE_CASE_NOT_OPEN'; end if; if not exists(select 1 from public.agencies where id=p_agency_id and status='approved') then raise exception 'BACKUP_AGENCY_NOT_APPROVED'; end if; if not exists(select 1 from public.guards where agency_id=p_agency_id and availability='available') then raise exception 'BACKUP_AGENCY_HAS_NO_AVAILABLE_GUARDS'; end if; update public.mission_rescue_cases set offered_agency_id=p_agency_id,offered_at=now() where id=v_case.id returning * into v_case; insert into public.mission_events(job_id,actor_user_id,event_type,payload) values(p_job_id,auth.uid(),'operations_rescue_backup_offered',jsonb_build_object('rescue_case_id',v_case.id,'backup_agency_id',p_agency_id)); insert into public.owner_audit_log(actor_user_id,action,target_type,target_id,payload) values(auth.uid(),'mission_rescue_backup_offered','marketplace_job',p_job_id,jsonb_build_object('rescue_case_id',v_case.id,'backup_agency_id',p_agency_id)); return to_jsonb(v_case); end $$;
revoke all on function public.offer_mission_rescue_to_backup(uuid,uuid) from public,anon;
grant execute on function public.offer_mission_rescue_to_backup(uuid,uuid) to authenticated;
